"""Bahasa Melayu — sirah (sira_001 … sira_150)."""

T = {
"sira_001": ("Di kota manakah Nabi Muhammad ﷺ dilahirkan?", ["Makkah", "Madinah", "Ta'if", "Baitulmaqdis"], "Nabi Muhammad ﷺ dilahirkan di Makkah, di wilayah Hijaz."),
"sira_002": ("Apakah nama tahun kelahiran Nabi ﷺ, yang ditandai dengan peristiwa gajah?", ["Tahun Gajah", "Tahun Kemenangan", "Tahun Unta", "Tahun Cahaya"], "Peristiwa gajah, ketika Allah melindungi Kaabah, diceritakan dalam surah Al-Fil."),
"sira_003": ("Siapakah nama isteri pertama Nabi ﷺ?", ["Khadijah", "Aisyah", "Hafsah", "Zainab"], "Khadijah binti Khuwailid ialah isteri pertama Nabi ﷺ dan orang pertama yang beriman kepada risalahnya."),
"sira_004": ("Di gua manakah Nabi ﷺ menerima wahyu pertama?", ["Gua Hira", "Gua Tsur", "Gua Ashabul Kahfi", "Gua Uhud"], "Wahyu pertama berlaku di Gua Hira, di Jabal Nur berhampiran Makkah."),
"sira_005": ("Malaikat manakah yang membawa wahyu kepada Nabi ﷺ?", ["Jibril", "Mikail", "Israfil", "Malik"], "Al-Quran menyebut dengan jelas bahawa Jibril membawa wahyu dengan izin Allah."),
"sira_006": ("Apakah nama penghijrahan Nabi ﷺ dan para sahabatnya dari Makkah ke Madinah?", ["Hijrah", "Isra'", "Mikraj", "Fathu Makkah"], "Hijrah merujuk kepada penghijrahan bersejarah ke Madinah, titik permulaan kalendar Islam."),
"sira_007": ("Ke kota manakah Nabi ﷺ dan Abu Bakar berhijrah?", ["Madinah", "Ta'if", "Damsyik", "Baitulmaqdis"], "Nabi ﷺ dan Abu Bakar berhijrah dari Makkah ke Madinah (ketika itu dinamakan Yathrib)."),
"sira_008": ("Al-Quran menggambarkan seorang sahabat sebagai «orang kedua daripada dua, ketika keduanya berada di dalam gua» semasa Hijrah. Siapakah dia?", ["Abu Bakar", "Umar", "Uthman", "Ali"], "Al-Quran merujuk kepada Abu Bakar, yang menemani Nabi ﷺ di Gua Tsur semasa Hijrah."),
"sira_009": ("Peperangan manakah, yang disebut dalam al-Quran, menyaksikan tentera Muslim yang kecil mengalahkan pasukan yang jauh lebih besar?", ["Perang Badar", "Perang Uhud", "Perang Khandak", "Perang Hunain"], "Di Badar, Allah mengurniakan kemenangan kepada sekumpulan kecil orang beriman ke atas tentera yang jauh lebih besar."),
"sira_010": ("Apakah nama kepulangan Nabi ﷺ dan para sahabatnya ke Makkah yang sebahagian besarnya secara aman?", ["Pembukaan Makkah (Fathu Makkah)", "Perang Makkah", "Kepungan Makkah", "Kejatuhan Makkah"], "Pembukaan Makkah berlaku sebahagian besarnya secara aman, tanpa pertumpahan darah yang meluas."),
"sira_011": ("Apakah nama khutbah terakhir yang disampaikan Nabi ﷺ menjelang akhir hayatnya?", ["Khutbah Perpisahan (Hajjatul Wada')", "Khutbah Makkah", "Khutbah Gua", "Khutbah Badar"], "Khutbah Perpisahan (Khutbatul Wada') disampaikan semasa haji terakhir Nabi ﷺ."),
"sira_012": ("Pada bulan apakah, menurut al-Quran, wahyu mula diturunkan?", ["Ramadan", "Muharam", "Rejab", "Zulhijah"], "Al-Quran menyatakan bahawa Ramadan ialah bulan al-Quran diturunkan."),
"sira_013": ("Apakah pekerjaan Nabi ﷺ sebelum menerima wahyu?", ["Pedagang/peniaga", "Hanya gembala", "Tukang besi", "Jurutulis"], "Nabi ﷺ bekerja dalam perdagangan, satu fakta yang mantap dalam sirahnya."),
"sira_014": ("Datuk Nabi ﷺ yang manakah menjaganya selepas kematian ibunya?", ["Abdul Muttalib", "Abu Talib", "Abu Lahab", "Abu Sufyan"], "Abdul Muttalib menjaga Muhammad ﷺ yang masih kecil selepas kematian ibunya Aminah."),
"sira_015": ("Bapa saudara manakah yang membesarkan Nabi ﷺ selepas kematian datuknya?", ["Abu Talib", "Al-Abbas", "Hamzah", "Abu Lahab"], "Abu Talib mengambil tanggungjawab membesarkan anak saudaranya selepas kematian Abdul Muttalib."),
"sira_016": ("Apakah nama perjalanan malam Nabi ﷺ dari Makkah ke Baitulmaqdis, yang disebut dalam al-Quran?", ["Isra'", "Hijrah", "Fath", "Ghazwah"], "Surah Al-Isra' dibuka dengan menggambarkan perjalanan malam yang ajaib ini."),
"sira_017": ("Anak perempuan Nabi ﷺ yang manakah berkahwin dengan Ali bin Abi Talib?", ["Fatimah", "Zainab", "Ruqayyah", "Ummu Kalthum"], "Fatimah, anak Nabi ﷺ dan Khadijah, berkahwin dengan Ali bin Abi Talib: satu fakta yang mantap."),
"sira_018": ("Bulan apakah yang menandakan permulaan tahun kalendar Islam, merujuk kepada Hijrah?", ["Muharam", "Ramadan", "Syawal", "Zulkaedah"], "Kalendar Islam bermula dengan bulan Muharam, merujuk kepada tahun Hijrah."),
"sira_019": ("Siapakah muazin pertama Islam, yang dipilih Nabi ﷺ untuk melaungkan azan?", ["Bilal bin Rabah", "Abu Bakar", "Umar bin al-Khattab", "Salman al-Farisi"], "Bilal, dengan suaranya yang merdu, dipilih sebagai muazin pertama Islam."),
"sira_020": ("Apakah masjid pertama yang diasaskan Nabi ﷺ setibanya berhampiran Madinah?", ["Masjid Quba'", "Masjidil Haram", "Masjid al-Aqsa", "Masjid Qiblatain"], "Setibanya di Quba', di pinggir Madinah, Nabi ﷺ mengasaskan masjid pertama di sana."),
"sira_021": ("Siapakah nama ibu Nabi ﷺ?", ["Aminah", "Khadijah", "Halimah", "Fatimah"], "Aminah binti Wahab ialah ibu Nabi ﷺ; Halimah ialah ibu susuannya."),
"sira_022": ("Siapakah nama bapa Nabi ﷺ, yang meninggal dunia sebelum kelahirannya?", ["Abdullah", "Abu Talib", "Abdul Muttalib", "Hamzah"], "Abdullah, anak Abdul Muttalib, meninggal dunia sebelum anaknya Muhammad ﷺ dilahirkan."),
"sira_023": ("Apakah gelaran yang diberikan penduduk Makkah kepada Nabi ﷺ sebelum kenabian, kerana kejujurannya?", ["Al-Amin (yang dipercayai)", "Al-Faruq", "As-Siddiq", "Saifullah"], "Sebelum kenabian lagi baginda digelar al-Amin: orang ramai mengamanahkan harta mereka kepadanya."),
"sira_024": ("Pada tahun Hijrah ke berapakah Pembukaan Makkah berlaku?", ["Tahun 8", "Tahun 2", "Tahun 5", "Tahun 10"], "Pada tahun 8 Hijrah Nabi ﷺ memasuki Makkah hampir tanpa pertempuran dan memaafkan penduduknya."),
"sira_025": ("Pada tahun Hijrah ke berapakah Nabi ﷺ menunaikan Haji Perpisahan?", ["Tahun 10", "Tahun 6", "Tahun 8", "Tahun 12"], "Haji Perpisahan berlaku pada tahun 10 Hijrah; Nabi ﷺ menyampaikan khutbah terakhirnya di sana."),
"sira_026": ("Berapa orang anak perempuan Nabi ﷺ?", ["4", "1", "2", "7"], "Zainab, Ruqayyah, Ummu Kalthum dan Fatimah: empat orang anak perempuan Nabi ﷺ."),
"sira_027": ("Apakah nama penduduk Madinah yang menyambut dan membantu orang Islam yang berhijrah?", ["Ansar (para penolong)", "Muhajirin", "Quraisy", "Tabiin"], "Ansar, «para penolong», berkongsi rumah dan harta dengan saudara mereka yang berhijrah."),
"sira_028": ("Apakah nama orang Islam yang meninggalkan Makkah untuk berhijrah ke Madinah?", ["Muhajirin (orang yang berhijrah)", "Ansar", "Hunafa'", "Ghuzat"], "Kaum Muhajirin meninggalkan rumah dan harta di Makkah demi memelihara iman mereka."),
"sira_029": ("Pada bulan apakah Perang Badar berlaku?", ["Ramadan", "Muharam", "Zulhijah", "Rejab"], "Perang Badar berlaku pada bulan Ramadan, tahun 2 Hijrah."),
"sira_030": ("Sebelum kiblat ditetapkan ke arah Kaabah, ke arah kota manakah orang Islam bersolat?", ["Baitulmaqdis", "Madinah", "Ta'if", "Damsyik"], "Orang Islam pada mulanya bersolat menghadap Baitulmaqdis; kemudian Allah memerintahkan menghadap Masjidil Haram (al-Quran 2:142-144)."),
"sira_031": ("Kabilah manakah yang Nabi Muhammad ﷺ berasal?", ["Quraisy", "Aus", "Khazraj", "Thaqif"], "Sebuah surah penuh dinamakan sempena kabilahnya: Quraisy."),
"sira_032": ("Daripada keturunan Quraisy yang manakah Nabi ﷺ berasal?", ["Bani Hasyim", "Bani Umaiyah", "Bani Makhzum", "Bani Tamim"], "Nabi ﷺ berasal daripada Bani Hasyim, keturunan moyangnya Hasyim."),
"sira_033": ("Siapakah nama ibu susuan yang menyusukan Nabi ﷺ di padang pasir?", ["Halimah as-Sa'diyah", "Aminah", "Khadijah", "Fatimah"], "Mengikut adat Makkah, bayi itu diamanahkan kepada ibu susuan Badwi: Halimah as-Sa'diyah."),
"sira_034": ("Bapa saudara Nabi ﷺ yang manakah, wira Badar, gugur syahid di Uhud?", ["Hamzah", "Abu Talib", "Al-Abbas", "Abu Lahab"], "Hamzah bin Abdul Muttalib berjuang di Badar dan terbunuh dalam Perang Uhud."),
"sira_035": ("Sepupu Nabi ﷺ yang manakah, yang dibesarkan di rumahnya, menjadi khalifah keempat?", ["Ali bin Abi Talib", "Ja'far", "Aqil", "Al-Abbas"], "Ali, anak Abu Talib, membesar bersama Nabi ﷺ dan merupakan khalifah ar-rasyidin keempat."),
"sira_036": ("Siapakah khalifah pertama selepas kewafatan Nabi ﷺ?", ["Abu Bakar", "Umar", "Uthman", "Ali"], "Abu Bakar as-Siddiq dipilih sebagai khalifah pertama."),
"sira_037": ("Apakah gelaran Abu Bakar, kerana mempercayai Nabi ﷺ tanpa ragu-ragu?", ["As-Siddiq (yang membenarkan)", "Al-Faruq", "Dzun-Nurain", "Saifullah"], "Abu Bakar digelar as-Siddiq, orang yang membenarkan dan mempercayai kebenaran."),
"sira_038": ("Apakah gelaran Umar bin al-Khattab?", ["Al-Faruq (pembeza antara yang benar dan yang batil)", "As-Siddiq", "Dzun-Nurain", "Al-Amin"], "Umar digelar al-Faruq, orang yang memisahkan kebenaran daripada kebatilan."),
"sira_039": ("Mengapakah Uthman bin Affan digelar «Dzun-Nurain», pemilik dua cahaya?", ["Dia berkahwin dengan dua orang anak perempuan Nabi ﷺ, seorang demi seorang", "Dia membawa dua pelita", "Dia menghafal al-Quran dua kali", "Dia berhijrah dua kali"], "Uthman berkahwin dengan Ruqayyah dan, selepas kematiannya, dengan Ummu Kalthum, kedua-duanya anak Nabi ﷺ."),
"sira_040": ("Dalam susunan apakah empat khalifah ar-rasyidin saling menggantikan?", ["Abu Bakar, Umar, Uthman, Ali", "Ali, Umar, Abu Bakar, Uthman", "Umar, Abu Bakar, Ali, Uthman", "Abu Bakar, Ali, Umar, Uthman"], "Abu Bakar, kemudian Umar, kemudian Uthman, kemudian Ali."),
"sira_041": ("Siapakah orang pertama yang beriman kepada risalah Nabi ﷺ?", ["Khadijah, isterinya", "Abu Bakar", "Ali", "Bilal"], "Khadijah beriman kepadanya sejak wahyu pertama dan menyokongnya."),
"sira_042": ("Siapakah yang membeli Bilal untuk membebaskannya daripada seksaan tuannya?", ["Abu Bakar", "Umar", "Hamzah", "Uthman"], "Abu Bakar membeli Bilal dan memerdekakannya."),
"sira_043": ("Siapakah syahid pertama dalam Islam, yang dibunuh di Makkah kerana imannya?", ["Sumayyah, ibu Ammar", "Asma'", "Ummu Salamah", "Safiyyah"], "Sumayyah binti Khayyat, ibu Ammar bin Yasir, dibunuh oleh Abu Jahal."),
"sira_044": ("Ke negeri manakah penghijrahan pertama orang Islam yang ditindas di Makkah berlaku?", ["Habsyah (Ethiopia)", "Parsi", "Yaman", "Mesir"], "Golongan pertama yang berhijrah pergi ke Habsyah, kepada seorang raja yang adil."),
"sira_045": ("Apakah gelaran raja Habsyah yang melindungi orang Islam dan yang Nabi ﷺ solatkan jenazahnya secara ghaib?", ["An-Najasyi", "Heraclius", "Kisra", "Al-Muqauqis"], "Nabi ﷺ mengumumkan kematian Najasyi pada hari ia berlaku dan menyolatkannya bersama para sahabat."),
"sira_046": ("Sahabat manakah yang berucap di hadapan Najasyi untuk menerangkan Islam?", ["Ja'far bin Abi Talib", "Uthman", "Bilal", "Mus'ab bin Umair"], "Ja'far menerangkan kepada raja apa yang diajarkan Nabi ﷺ, dan membacakan kepadanya ayat-ayat surah Maryam."),
"sira_047": ("Bapa saudara Nabi ﷺ yang manakah dikutuk namanya dalam al-Quran?", ["Abu Lahab", "Abu Talib", "Al-Abbas", "Hamzah"], "«Binasalah kedua-dua tangan Abu Lahab, dan binasalah dia.»"),
"sira_048": ("Apakah nama tahun Nabi ﷺ kehilangan isterinya Khadijah dan bapa saudaranya Abu Talib?", ["Tahun Dukacita ('Amul Huzn)", "Tahun Gajah", "Tahun Perutusan", "Tahun Kebuluran"], "Dua penyokong utama Nabi ﷺ meninggal dunia pada tahun yang sama, yang dikenali sebagai Tahun Dukacita."),
"sira_049": ("Di kota manakah Nabi ﷺ dihalau dan dicederakan selepas berdakwah, sebelum baginda enggan membiarkan malaikat gunung menghancurkan penduduknya?", ["Ta'if", "Madinah", "Khaibar", "Tabuk"], "Ditolak di Ta'if, baginda enggan memusnahkan penduduknya, dengan harapan keturunan mereka akan menyembah Allah."),
"sira_050": ("Semasa Isra' dan Mikraj, kewajipan apakah yang difardukan ke atas orang Islam?", ["Solat lima waktu", "Puasa Ramadan", "Zakat", "Haji"], "Solat difardukan pada malam itu, dikurangkan daripada lima puluh kepada lima, dengan ganjaran lima puluh."),
"sira_051": ("Pokok apakah, di sempadan terjauh, yang Nabi ﷺ lihat semasa Mikraj, menurut surah An-Najm?", ["Sidratul Muntaha", "Pokok zaitun yang diberkati", "Pokok kurma Maryam", "Pokok Tuba"], "«Di sisi Sidratul Muntaha», pokok bidara di sempadan terjauh."),
"sira_052": ("Apakah nama baiah yang diberikan penduduk Yathrib kepada Nabi ﷺ sebelum Hijrah?", ["Baiah Aqabah", "Perjanjian Hudaibiyah", "Baiah di bawah pokok", "Piagam Madinah"], "Penduduk Yathrib berbaiah kepada Nabi ﷺ di Aqabah, berhampiran Mina, sebelum Hijrah."),
"sira_053": ("Sahabat manakah yang Nabi ﷺ hantar ke Yathrib, sebelum Hijrah, untuk mengajar Islam?", ["Mus'ab bin Umair", "Bilal", "Abu Hurairah", "Khalid bin al-Walid"], "Mus'ab bin Umair ialah utusan pertama ke Yathrib, mengajar al-Quran kepada orang Islam yang baru."),
"sira_054": ("Siapakah yang tidur di tempat tidur Nabi ﷺ pada malam baginda berangkat untuk Hijrah?", ["Ali bin Abi Talib", "Abu Bakar", "Zaid bin Harithah", "Bilal"], "Ali menggantikan tempatnya di tempat tidur untuk mengelirukan pengintip, kemudian memulangkan barang amanah kepada penduduk Makkah."),
"sira_055": ("Di gua manakah Nabi ﷺ dan Abu Bakar bersembunyi semasa Hijrah?", ["Gua Tsur", "Gua Hira", "Gua Uhud", "Gua Ta'if"], "Mereka bersembunyi selama tiga hari di Gua Tsur, di selatan Makkah."),
"sira_056": ("Anak perempuan Abu Bakar yang manakah membawa bekalan ke gua dan digelar «pemilik dua tali pinggang»?", ["Asma'", "Aisyah", "Ummu Kalthum", "Ummu Ruman"], "Asma' mengoyakkan tali pinggangnya menjadi dua untuk mengikat bekalan: maka digelar «Dzatun Nitaqain»."),
"sira_057": ("Apakah yang berlaku kepada Suraqah, yang mengejar Nabi ﷺ semasa Hijrah?", ["Kudanya terbenam ke dalam tanah, dan dia meminta jaminan keselamatan", "Dia berjaya mengejar Nabi ﷺ", "Dia sesat di padang pasir", "Dia jatuh sakit"], "Kaki kudanya terbenam ke dalam tanah; Suraqah meminta jaminan keselamatan dan pergi tanpa mengapa-apakan."),
"sira_058": ("Apakah nama lama Madinah, yang disebut dalam al-Quran?", ["Yathrib", "Taibah", "Khaibar", "Bakkah"], "«Wahai penduduk Yathrib…», firman al-Quran, mengenang Perang Ahzab."),
"sira_059": ("Apakah nama unta betina Nabi ﷺ, yang melutut di Hudaibiyah?", ["Al-Qaswa'", "Al-Buraq", "Ad-Duldul", "Al-'Adba'"], "Di Hudaibiyah, Al-Qaswa' melutut; Nabi ﷺ bersabda: «Yang menahan gajah telah menahannya.»"),
"sira_060": ("Apakah yang Nabi ﷺ tetapkan antara Muhajirin dan Ansar setibanya di Madinah?", ["Persaudaraan, secara berpasangan", "Cukai", "Tentera", "Pasar"], "Baginda mempersaudarakan orang yang berhijrah dengan para penolong, setiap Muhajir dipasangkan dengan seorang saudara daripada Ansar."),
"sira_061": ("Apakah nama dokumen yang Nabi ﷺ gunakan untuk mengatur hubungan antara masyarakat Madinah?", ["Sahifah (Piagam) Madinah", "Perjanjian Hudaibiyah", "Perjanjian Ta'if", "Piagam Quba'"], "Sahifah menetapkan hak dan tanggungjawab orang Islam dan kabilah-kabilah lain di Madinah."),
"sira_062": ("Apakah nama sahabat-sahabat miskin yang tinggal di masjid Nabi ﷺ?", ["Ahlus Suffah (penghuni serambi)", "Muhajirin", "Ansar", "Hawariyyun"], "Abu Hurairah menceritakan bahawa dia termasuk dalam kalangan Ahlus Suffah, yang diberi makan oleh Nabi ﷺ."),
"sira_063": ("Berapa tahun selepas Hijrah Perang Badar berlaku?", ["Dua", "Lima", "Lapan", "Sepuluh"], "Badar berlaku pada tahun 2 Hijrah, pada bulan Ramadan."),
"sira_064": ("Berapa malaikat yang Allah janjikan sebagai bantuan kepada orang beriman di Badar?", ["Seribu", "Seratus", "Sepuluh", "Seratus ribu"], "«Aku akan membantu kamu dengan seribu malaikat yang datang berturut-turut.»"),
"sira_065": ("Di Uhud, kesilapan pemanah yang manakah mengubah keadaan peperangan?", ["Mereka meninggalkan bukit walaupun diperintahkan Nabi ﷺ", "Mereka memanah terlalu awal", "Mereka tertidur", "Mereka bertukar pihak"], "Nabi ﷺ telah memerintahkan para pemanah supaya tidak beredar; kebanyakan mereka turun mengambil harta rampasan dan pasukan berkuda musuh memintas mereka."),
"sira_066": ("Berhampiran kota manakah terletaknya Gunung Uhud?", ["Madinah", "Makkah", "Ta'if", "Baitulmaqdis"], "Gunung Uhud terletak di utara Madinah; peperangan berlaku di kakinya."),
"sira_067": ("Sahabat manakah yang mencadangkan menggali parit untuk mempertahankan Madinah daripada tentera bersekutu?", ["Salman al-Farisi", "Bilal", "Abu Dzar", "Suhaib"], "Salman al-Farisi mencadangkan parit, satu taktik yang dikenali di Parsi."),
"sira_068": ("Dengan nama lain apakah Perang Khandak dikenali, sempena surah yang membicarakannya?", ["Perang Ahzab (tentera bersekutu)", "Perang Badar", "Perang Hunain", "Perang Mu'tah"], "Surah Al-Ahzab mengenang tentera bersekutu yang mengepung Madinah dan angin yang dihantar menentang mereka."),
"sira_069": ("Apakah nama baiah yang diberikan di bawah sebatang pokok di Hudaibiyah, yang Allah nyatakan Dia reda dengannya?", ["Baiatur Ridwan", "Baiah Aqabah", "Baiatun Nisa'", "Baiatul Fath"], "«Sesungguhnya Allah reda kepada orang beriman ketika mereka berbaiah kepadamu di bawah pokok itu.»"),
"sira_070": ("Surah manakah yang dibuka dengan «Sesungguhnya Kami telah memberikan kepadamu kemenangan yang nyata», diturunkan selepas Perjanjian Hudaibiyah?", ["Al-Fath", "An-Nasr", "Al-Anfal", "At-Taubah"], "«Sesungguhnya Kami telah memberikan kepadamu kemenangan yang nyata»: surah Al-Fath."),
"sira_071": ("Pada tahun Hijrah ke berapakah Perjanjian Hudaibiyah dimeterai?", ["6 Hijrah", "2 Hijrah", "8 Hijrah", "10 Hijrah"], "Perjanjian Hudaibiyah dimeterai pada tahun 6 Hijrah antara orang Islam dan Quraisy."),
"sira_072": ("Maharaja Rom manakah yang menerima surat Nabi ﷺ yang mengajaknya kepada Islam dan menyoal Abu Sufyan tentang baginda?", ["Heraclius", "Nero", "Constantine", "Justinian"], "Heraclius menyoal Abu Sufyan tentang Nabi ﷺ selepas menerima suratnya."),
"sira_073": ("Kepada siapakah Nabi ﷺ menyerahkan panji di Khaibar, selepas bersabda: «Esok aku akan memberikannya kepada seorang lelaki yang dicintai Allah dan Rasul-Nya»?", ["Ali bin Abi Talib", "Abu Bakar", "Umar", "Sa'ad bin Abi Waqqas"], "Baginda memanggil Ali, yang sakit mata; baginda menyapukan air liurnya, menyembuhkannya dan memberikannya panji."),
"sira_074": ("Tiga orang panglima manakah yang gugur seorang demi seorang dalam Perang Mu'tah?", ["Zaid bin Harithah, Ja'far bin Abi Talib dan Abdullah bin Rawahah", "Hamzah, Mus'ab dan Sa'ad", "Abu Bakar, Umar dan Uthman", "Bilal, Salman dan Suhaib"], "Nabi ﷺ mengumumkan di Madinah: «Zaid mengambil panji lalu gugur, kemudian Ja'far, kemudian Ibnu Rawahah… kemudian sebilah pedang Allah mengambilnya.»"),
"sira_075": ("Sahabat manakah yang Nabi ﷺ gelar «sebilah pedang antara pedang-pedang Allah»?", ["Khalid bin al-Walid", "Ali", "Hamzah", "Abu Ubaidah"], "Di Mu'tah, «sebilah pedang antara pedang-pedang Allah», Khalid bin al-Walid, mengambil panji dan menyelamatkan tentera."),
"sira_076": ("Apakah yang Nabi ﷺ lakukan terhadap berhala-berhala di sekeliling Kaabah semasa Pembukaan Makkah?", ["Baginda merobohkannya sambil membaca «Kebenaran telah datang dan kebatilan telah lenyap»", "Baginda menjualnya", "Baginda membawanya ke Madinah", "Baginda membiarkannya"], "Baginda memukul berhala-berhala itu dengan tongkatnya sambil bersabda: «Kebenaran telah datang dan kebatilan telah lenyap.»"),
"sira_077": ("Siapakah yang melaungkan azan dari atas Kaabah pada hari Pembukaan Makkah?", ["Bilal", "Abu Bakar", "Ali", "Umar"], "Nabi ﷺ memerintahkan Bilal naik ke atas Kaabah dan melaungkan azan."),
"sira_078": ("Apakah yang Nabi ﷺ katakan kepada penduduk Makkah yang tewas dan pernah menindasnya, pada hari pembukaan?", ["«Pergilah, kamu semua bebas»", "«Kamu akan dihakimi esok»", "«Tinggalkan kota ini»", "«Bayarlah tebusan»"], "Baginda memaafkan mereka: «Pergilah, kamu semua bebas.»"),
"sira_079": ("Dalam peperangan manakah, yang dinamakan dalam al-Quran, orang Islam pada mulanya terkejut walaupun jumlah mereka ramai?", ["Hunain", "Badar", "Uhud", "Khaibar"], "«Pada hari Hunain, ketika jumlah kamu yang ramai menjadikan kamu bangga, tetapi ia tidak memberi manfaat sedikit pun kepada kamu.»"),
"sira_080": ("Sahabat manakah yang tidak menyertai ekspedisi Tabuk, mengaku dengan jujur dan diampunkan melalui wahyu?", ["Ka'ab bin Malik", "Abu Dzar", "Anas bin Malik", "Abu Hurairah"], "Ka'ab bin Malik berkata benar, menanggung lima puluh hari dipulaukan, kemudian Allah menurunkan keampunannya (9:118)."),
"sira_081": ("Apakah nama tahun 9 Hijrah, ketika banyak kabilah datang ke Madinah untuk memeluk Islam?", ["Tahun Perutusan ('Amul Wufud)", "Tahun Dukacita", "Tahun Gajah", "Tahun Kemarau"], "Selepas Pembukaan Makkah, perutusan kabilah-kabilah Arab membanjiri Madinah."),
"sira_082": ("Di manakah Nabi ﷺ menyampaikan Khutbah Perpisahan?", ["Di Arafah", "Di Madinah", "Di Gunung Uhud", "Di Ta'if"], "Khutbah Perpisahan disampaikan di Arafah, semasa Haji Perpisahan."),
"sira_083": ("Ayat manakah, yang diturunkan semasa Haji Perpisahan, mengumumkan bahawa agama telah disempurnakan?", ["«Pada hari ini Aku telah sempurnakan bagimu agamamu»", "«Bacalah dengan nama Tuhanmu»", "«Apabila datang pertolongan Allah»", "«Katakanlah: Dialah Allah, Yang Maha Esa»"], "«Pada hari ini Aku telah sempurnakan bagimu agamamu dan Aku telah cukupkan nikmat-Ku kepadamu.»"),
"sira_084": ("Di kota manakah Nabi ﷺ wafat dan dimakamkan?", ["Madinah", "Makkah", "Baitulmaqdis", "Ta'if"], "Baginda wafat di Madinah pada tahun 11 Hijrah dan dimakamkan di sana."),
"sira_085": ("Di bilik isteri yang manakah Nabi ﷺ dimakamkan?", ["Aisyah", "Khadijah", "Hafsah", "Ummu Salamah"], "Baginda dimakamkan di tempat baginda wafat, di bilik Aisyah, yang kini berada di dalam Masjid Nabawi."),
"sira_086": ("Siapakah yang mengisytiharkan, ketika kewafatan Nabi ﷺ: «Sesiapa yang menyembah Muhammad, maka Muhammad telah wafat; sesiapa yang menyembah Allah, maka Allah Maha Hidup»?", ["Abu Bakar", "Umar", "Ali", "Bilal"], "Abu Bakar menenangkan para sahabat dan membaca: «Muhammad hanyalah seorang rasul…» (3:144)."),
"sira_087": ("Siapakah nama dua orang cucu Nabi ﷺ, anak-anak Fatimah dan Ali?", ["Al-Hasan dan Al-Husain", "Ibrahim dan Ismail", "Zaid dan Usamah", "Ja'far dan Aqil"], "Al-Hasan dan Al-Husain, yang amat disayangi Nabi ﷺ."),
"sira_088": ("Isteri Nabi ﷺ yang manakah anak Abu Bakar?", ["Aisyah", "Hafsah", "Zainab", "Saudah"], "Aisyah, anak Abu Bakar, meriwayatkan sejumlah besar hadis."),
"sira_089": ("Isteri Nabi ﷺ yang manakah anak Umar bin al-Khattab?", ["Hafsah", "Aisyah", "Ummu Habibah", "Maimunah"], "Hafsah binti Umar; naskhah al-Quran pertama yang dihimpunkan disimpan di sisinya."),
"sira_090": ("Sahabat manakah yang meriwayatkan hadis paling banyak daripada Nabi ﷺ?", ["Abu Hurairah", "Anas bin Malik", "Abdullah bin Umar", "Jabir"], "Abu Hurairah, yang sentiasa bersama Nabi ﷺ, ialah sahabat yang meriwayatkan hadis paling banyak."),
"sira_091": ("Sahabat muda manakah yang berkhidmat kepada Nabi ﷺ selama sepuluh tahun tanpa pernah mendengar teguran?", ["Anas bin Malik", "Usamah bin Zaid", "Ibnu Abbas", "Zaid bin Thabit"], "Anas berkata: «Aku berkhidmat kepada Nabi ﷺ selama sepuluh tahun; baginda tidak pernah berkata 'ah' kepadaku, mahupun 'mengapa engkau lakukan itu?'»"),
"sira_092": ("Untuk sepupu muda yang manakah Nabi ﷺ berdoa: «Ya Allah, ajarkanlah dia al-Kitab»?", ["Abdullah bin Abbas", "Ali", "Ja'far", "Usamah"], "Nabi ﷺ memeluk Ibnu Abbas dan berdoa: «Ya Allah, ajarkanlah dia al-Kitab.»"),
"sira_093": ("Sahabat manakah yang Nabi ﷺ hantar ke Yaman, dengan pesanan supaya menyeru dahulu kepada keesaan Allah?", ["Mu'az bin Jabal", "Bilal", "Abu Musa seorang", "Zaid bin Harithah"], "«Engkau akan mendatangi kaum Ahli Kitab: serulah mereka dahulu supaya bersaksi bahawa tiada tuhan selain Allah…»"),
"sira_094": ("Sahabat manakah yang Nabi ﷺ gelar «orang yang dipercayai (amin) umat ini»?", ["Abu Ubaidah bin al-Jarrah", "Abu Bakar", "Uthman", "Khalid"], "«Setiap umat mempunyai orang yang dipercayai, dan orang yang dipercayai umat ini ialah Abu Ubaidah bin al-Jarrah.»"),
"sira_095": ("Sahabat manakah, seorang penulis wahyu, yang ditugaskan Abu Bakar menghimpunkan al-Quran?", ["Zaid bin Thabit", "Abu Hurairah", "Anas bin Malik", "Salman"], "Selepas Perang Yamamah, Abu Bakar menugaskan Zaid bin Thabit menghimpunkan al-Quran."),
"sira_096": ("Di bawah khalifah manakah naskhah rasmi al-Quran dihantar ke wilayah-wilayah?", ["Uthman bin Affan", "Abu Bakar", "Umar", "Ali"], "Uthman menyalin mushaf dan menghantar satu naskhah ke setiap wilayah."),
"sira_097": ("Dari negeri manakah sahabat Salman, yang digelar «al-Farisi», berasal?", ["Parsi", "Habsyah", "Rom", "Yaman"], "Salman al-Farisi, «orang Parsi», datang dari Parsi mencari kebenaran."),
"sira_098": ("Sahabat manakah, yang datang dari negeri Rom, digelar «ar-Rumi»?", ["Suhaib", "Bilal", "Salman", "Abu Dzar"], "Suhaib ar-Rumi membesar dalam kalangan orang Rom sebelum memeluk Islam di Makkah."),
"sira_099": ("Apakah nama masjid Nabi ﷺ di Madinah?", ["Masjid Nabawi", "Masjidil Haram", "Masjid al-Aqsa", "Masjid Quba'"], "Masjid yang baginda asaskan di Madinah dinamakan Masjid Nabi, al-Masjid an-Nabawi."),
"sira_100": ("Berapa kali nama «Muhammad» disebut dalam al-Quran?", ["Empat", "Satu", "Dua belas", "Seratus"], "Dalam ayat 3:144, 33:40, 47:2 dan 48:29; nama «Ahmad» disebut dalam 61:6."),
"sira_101": ("Bagaimanakah al-Quran menggambarkan Nabi ﷺ bagi orang beriman, dalam ayat 33:21?", ["Teladan yang baik", "Hakim yang tegas", "Seorang raja", "Seorang penyair"], "«Sesungguhnya telah ada pada diri Rasulullah itu teladan yang baik bagi kamu.»"),
"sira_102": ("Apakah kuniah (gelaran kebapaan) Nabi ﷺ?", ["Abul Qasim", "Abu Bakar", "Abu Abdullah", "Abu Talib"], "Baginda digelar Abul Qasim, sempena anak sulungnya Al-Qasim."),
"sira_103": ("Siapakah nama anak lelaki Nabi ﷺ yang lahir di Madinah dan meninggal ketika masih kecil?", ["Ibrahim", "Al-Qasim", "Abdullah", "Al-Hasan"], "Ibrahim, lahir di Madinah, meninggal ketika masih bayi; Nabi ﷺ menangis dan bersabda bahawa hati bersedih tanpa mengucapkan apa yang dimurkai Allah."),
"sira_104": ("Untuk siapakah Nabi ﷺ mengetuai kafilah perdagangan ke Syam sebelum kenabian?", ["Khadijah", "Abu Bakar", "Abu Sufyan", "Al-Abbas"], "Khadijah, seorang pedagang yang kaya, mengamanahkan kafilahnya ke Syam kepada baginda, kemudian melamarnya."),
"sira_105": ("Bagaimanakah Muhammad ﷺ muda menyelesaikan pertikaian kabilah-kabilah tentang meletakkan semula Hajar Aswad?", ["Baginda meletakkannya di atas sehelai kain yang diangkat setiap kabilah, kemudian meletakkannya sendiri", "Baginda mengangkatnya seorang diri", "Baginda mengundi", "Baginda menyerahkannya kepada Abu Bakar"], "Baginda membentangkan sehelai kain, meletakkan Hajar Aswad di atasnya, menyuruh ketua-ketua kabilah mengangkat kain itu bersama, kemudian meletakkannya dengan tangannya sendiri."),
"sira_106": ("Pada usia berapakah Nabi ﷺ menerima wahyu pertama?", ["Empat puluh", "Dua puluh lima", "Lima puluh", "Enam puluh"], "Wahyu bermula ketika baginda berusia empat puluh tahun, di Gua Hira."),
"sira_107": ("Kepada sepupu Khadijah yang manakah, yang berilmu tentang kitab-kitab, Nabi ﷺ dibawa selepas wahyu pertama?", ["Waraqah bin Naufal", "Abu Talib", "Abu Lahab", "Al-Walid"], "Waraqah berkata: «Inilah an-Namus (malaikat) yang Allah utuskan kepada Musa.»"),
"sira_108": ("Di bukit manakah Nabi ﷺ naik untuk menyeru Quraisy secara terbuka, selepas ayat «Berilah amaran kepada kaum kerabatmu yang terdekat»?", ["Safa", "Uhud", "Arafah", "Hira"], "Baginda naik ke Bukit Safa, memanggil suku-suku Quraisy dan memberi amaran kepada mereka tentang azab yang dahsyat."),
"sira_109": ("Khalifah manakah yang menetapkan kalendar Islam bermula dari tahun Hijrah?", ["Umar bin al-Khattab", "Abu Bakar", "Uthman", "Ali"], "Di bawah pemerintahan Umar, Hijrah dipilih sebagai titik permulaan kalendar."),
"sira_110": ("Berapa tahun Nabi ﷺ tinggal di Madinah selepas Hijrah?", ["Sepuluh", "Tiga", "Dua puluh", "Tiga belas"], "Baginda tinggal sepuluh tahun di Madinah, dari Hijrah hingga kewafatannya pada tahun 11 Hijrah."),
"sira_111": ("Berapa tahun Nabi ﷺ berdakwah di Makkah sebelum Hijrah?", ["Tiga belas", "Tiga", "Sepuluh", "Dua puluh tiga"], "Tiga belas tahun di Makkah, kemudian sepuluh tahun di Madinah: dua puluh tiga tahun kerasulan."),
"sira_112": ("Sahabat manakah, seorang penyair, mempertahankan Nabi ﷺ dengan syairnya dan baginda memohon sokongan Jibril untuknya?", ["Hassan bin Thabit", "Ka'ab bin Malik", "Abdullah bin Rawahah", "Labid"], "Nabi ﷺ bersabda kepada Hassan: «Balaslah mereka, dan Jibril bersamamu.»"),
"sira_113": ("Sahabat manakah yang Nabi ﷺ katakan telah dikurniakan «salah satu seruling keluarga Daud» kerana bacaannya yang merdu?", ["Abu Musa al-Asy'ari", "Bilal", "Ubai bin Ka'ab", "Ibnu Mas'ud"], "Mendengar bacaannya, Nabi ﷺ bersabda bahawa Abu Musa telah dikurniakan salah satu seruling keluarga Daud."),
"sira_114": ("Nabi ﷺ menganjurkan mempelajari al-Quran daripada empat orang sahabat. Yang manakah antara berikut salah seorang daripada mereka?", ["Abdullah bin Mas'ud", "Abu Hurairah", "Anas bin Malik", "Khalid bin al-Walid"], "«Pelajarilah al-Quran daripada empat orang: Ibnu Mas'ud, Salim, Mu'az bin Jabal dan Ubai bin Ka'ab.»"),
"sira_115": ("Dalam peperangan manakah Nabi ﷺ cedera di wajah dan patah gigi?", ["Uhud", "Badar", "Hunain", "Khaibar"], "Di Uhud, gigi baginda patah dan wajahnya cedera."),
"sira_116": ("Kepada sahabat manakah, seorang pemanah di Uhud, Nabi ﷺ bersabda: «Panahlah! Ayah dan ibuku menjadi tebusanmu»?", ["Sa'ad bin Abi Waqqas", "Talhah", "Az-Zubair", "Ali"], "Nabi ﷺ menghulurkan anak panah kepadanya sambil bersabda: «Panahlah, ayah dan ibuku menjadi tebusanmu.»"),
"sira_117": ("Kafilah manakah yang orang Islam keluar untuk memintasnya, yang membawa kepada Perang Badar?", ["Kafilah Abu Sufyan, yang pulang dari Syam", "Kafilah Najasyi", "Kafilah Parsi", "Kafilah Ta'if"], "Kafilah Quraisy yang dipimpin Abu Sufyan terlepas, tetapi tentera Makkah datang ke Badar."),
"sira_118": ("Bilakah ketua Makkah Abu Sufyan memeluk Islam?", ["Semasa Pembukaan Makkah", "Sebelum Hijrah", "Semasa Badar", "Selepas kewafatan Nabi ﷺ"], "Abu Sufyan memeluk Islam pada malam sebelum Nabi ﷺ memasuki Makkah."),
"sira_119": ("Mata air apakah yang memancar untuk Hajar dan anaknya Ismail di lembah Makkah?", ["Zamzam", "Sungai Nil", "Sungai Furat", "Sungai Jordan"], "Seorang malaikat memukul tanah dan air Zamzam memancar; Hajar membuat kolam di sekelilingnya."),
"sira_120": ("Apakah yang terukir pada cincin Nabi ﷺ?", ["«Muhammad Rasulullah»", "«Allahu Akbar»", "«La ilaha illallah»", "Namanya sahaja"], "Cincin peraknya bertulis «Muhammad Rasulullah» dalam tiga baris."),
"sira_121": ("Makanan apakah yang disukai Nabi ﷺ, menurut Aisyah?", ["Manisan dan madu", "Ikan", "Rempah yang kuat", "Cuka sahaja"], "Aisyah meriwayatkan bahawa Nabi ﷺ menyukai makanan manis dan madu."),
"sira_122": ("Pada hari apakah dalam seminggu Nabi ﷺ dilahirkan, hari yang baginda juga berpuasa?", ["Isnin", "Jumaat", "Sabtu", "Rabu"], "Ketika ditanya tentang puasa hari Isnin, baginda bersabda: «Itulah hari aku dilahirkan dan hari wahyu diturunkan kepadaku.»"),
"sira_123": ("Di manakah «khatam kenabian» pada tubuh Nabi ﷺ?", ["Di antara dua bahunya", "Di tangannya", "Di dahinya", "Di dadanya"], "Khatam kenabian terletak di antara dua bahunya."),
"sira_124": ("Daripada kayu apakah mimbar Nabi ﷺ dibuat, oleh seorang tukang kayu?", ["Kayu tamarisk (athl)", "Kayu cedar", "Kayu zaitun", "Kayu kurma"], "Nabi ﷺ meminta dibuat sebuah mimbar daripada kayu tamarisk, dari mana baginda berucap kepada orang ramai."),
"sira_125": ("Dua kabilah besar Madinah yang manakah membentuk Ansar?", ["Aus dan Khazraj", "Quraisy dan Thaqif", "Tamim dan Hawazin", "Kindah dan Hamdan"], "Aus dan Khazraj, yang lama bermusuhan, bersatu dalam Islam dan menjadi Ansar."),
"sira_126": ("Gelaran apakah yang al-Quran berikan kepada isteri-isteri Nabi ﷺ?", ["Ibu-ibu orang beriman (Ummahatul Mukminin)", "Permaisuri-permaisuri Madinah", "Anak-anak perempuan Quraisy", "Penjaga-penjaga Kitab"], "«Isteri-isterinya adalah ibu-ibu mereka»: Ummahatul Mukminin."),
"sira_127": ("Pada tahun Masihi berapakah Hijrah berlaku?", ["622", "570", "632", "610"], "Hijrah, pada tahun 622, menandakan permulaan kalendar Islam."),
"sira_128": ("Apakah jawapan Abdurrahman bin Auf apabila saudara Ansarnya menawarkan separuh hartanya?", ["«Tunjukkan aku pasar»", "Dia menerima semuanya", "Dia meminta sebuah rumah", "Dia enggan berbicara"], "Dia berkata: «Semoga Allah memberkati harta dan keluargamu; tunjukkan sahaja aku pasar», dan dia berjaya melalui perdagangan."),
"sira_129": ("Sahabat manakah yang Nabi ﷺ tanya ayat al-Quran yang mana paling agung, sebelum mengucapkan tahniah atas jawapannya (Ayat Kursi)?", ["Ubai bin Ka'ab", "Abu Bakar", "Zaid bin Thabit", "Bilal"], "Ubai menjawab: «Allah, tiada tuhan selain Dia, Yang Maha Hidup…»; Nabi ﷺ bersabda: «Semoga ilmu menggembirakanmu, Abul Munzir!»"),
"sira_130": ("Bagaimanakah tapak masjid Nabi ﷺ di Madinah dipilih?", ["Di tempat unta betinanya melutut", "Melalui undian", "Di tengah pasar", "Di Gunung Uhud"], "Baginda membiarkan unta betinanya berjalan bebas: di tempat ia melutut, masjid itu dibina."),
"sira_131": ("Berapa orang anak lelaki Nabi ﷺ, yang semuanya meninggal ketika kecil?", ["Tiga", "Satu", "Lima", "Tiada"], "Al-Qasim dan Abdullah, daripada Khadijah, dan Ibrahim, yang lahir di Madinah."),
"sira_132": ("Sahabat manakah, yang dimerdekakan Nabi ﷺ dan dibesarkan seperti anak, merupakan bapa Usamah?", ["Zaid bin Harithah", "Bilal", "Salman", "Ammar"], "Zaid bin Harithah, kesayangan Nabi ﷺ, ialah bapa Usamah bin Zaid."),
"sira_133": ("Sahabat muda manakah yang Nabi ﷺ lantik memimpin tentera tidak lama sebelum kewafatannya, walaupun masih muda?", ["Usamah bin Zaid", "Anas bin Malik", "Ibnu Abbas", "Ibnu Umar"], "Nabi ﷺ memberikan Usamah pimpinan dan menjawab mereka yang mengkritik usianya bahawa dia layak, seperti bapanya."),
"sira_134": ("Datuk Nabi ﷺ yang manakah menggali semula telaga Zamzam, yang telah lama tertimbus?", ["Abdul Muttalib", "Hasyim", "Abdul Manaf", "Qusai"], "Abdul Muttalib menggali semula Zamzam dan menguruskannya untuk para jemaah."),
"sira_135": ("Lebih kurang berapa orang yang menyertai Nabi ﷺ dalam Perang Badar?", ["Sedikit lebih daripada tiga ratus", "Sepuluh ribu", "Seribu", "Lima puluh"], "Orang Islam di Badar berjumlah sedikit lebih daripada tiga ratus, menghadapi tentera yang jauh lebih besar."),
"sira_136": ("Pada bulan apakah dalam kalendar Islam Nabi ﷺ dilahirkan?", ["Rabiulawal", "Ramadan", "Muharam", "Zulhijah"], "Baginda dilahirkan pada bulan Rabiulawal, dalam Tahun Gajah."),
"sira_137": ("Pada bulan apakah Nabi ﷺ tiba di Madinah semasa Hijrah?", ["Rabiulawal", "Ramadan", "Muharam", "Rejab"], "Baginda tiba di Madinah pada bulan Rabiulawal, selepas singgah di Quba'."),
"sira_138": ("Perjanjian apakah yang Quraisy buat untuk memulaukan Bani Hasyim, yang melindungi Nabi ﷺ?", ["Pemulauan: tiada perdagangan atau perkahwinan dengan mereka", "Gencatan senjata sepuluh tahun", "Pembahagian Kaabah", "Pakatan ketenteraan"], "Quraisy menandatangani perjanjian pemulauan, dan Bani Hasyim dikurung di sebuah lembah selama bertahun-tahun."),
"sira_139": ("Bagaimanakah Nabi ﷺ memulakan dakwahnya di Makkah, sebelum seruan terbuka?", ["Dengan menyeru orang terdekatnya secara sulit", "Dengan tentera", "Dengan surat kepada raja-raja", "Dengan haji"], "Baginda mula-mula menyeru kaum kerabat dan sahabatnya secara sulit, sebelum dakwah menjadi terbuka."),
"sira_140": ("Antara dua bukit manakah Hajar berlari mencari air untuk Ismail?", ["Safa dan Marwah", "Uhud dan Tsur", "Arafah dan Mina", "Hira dan Tsur"], "Dia berlari tujuh kali antara Safa dan Marwah: asal usul sa'i para jemaah."),
"sira_141": ("Tentang cucu yang manakah Nabi ﷺ bersabda: «Anakku ini seorang sayyid; Allah akan mendamaikan dua kumpulan orang Islam melaluinya»?", ["Al-Hasan", "Al-Husain", "Usamah", "Ibnu Abbas"], "Al-Hasan bin Ali kemudiannya mendamaikan dua kumpulan besar orang Islam, sebagaimana yang Nabi ﷺ ramalkan."),
"sira_142": ("Siapakah nama anak perempuan Nabi ﷺ, ibu Al-Hasan dan Al-Husain?", ["Fatimah", "Zainab", "Ruqayyah", "Ummu Kalthum"], "Fatimah, isteri Ali, ialah ibu Al-Hasan dan Al-Husain."),
"sira_143": ("Siapakah anak perempuan sulung Nabi ﷺ?", ["Zainab", "Fatimah", "Ruqayyah", "Ummu Kalthum"], "Zainab ialah yang sulung antara empat anak perempuan Nabi ﷺ."),
"sira_144": ("Sahabat manakah, bekas hamba berketurunan Habsyah, dipilih sebagai muazin kerana suaranya yang merdu?", ["Bilal bin Rabah", "Salman", "Suhaib", "Zaid"], "Bilal, yang dimerdekakan Abu Bakar, menjadi muazin Nabi ﷺ."),
"sira_145": ("Tentang sahabat manakah Nabi ﷺ bersabda: «Sekiranya aku mengambil seorang khalil (sahabat karib) dalam kalangan manusia, nescaya dialah orangnya»?", ["Abu Bakar", "Umar", "Ali", "Uthman"], "«Sekiranya aku mengambil seorang khalil daripada umatku, nescaya aku memilih Abu Bakar, tetapi dia adalah saudara dan sahabatku.»"),
"sira_146": ("Kota manakah, bersama Makkah, dinamakan «al-Haramain», dua tanah suci?", ["Madinah", "Baitulmaqdis", "Ta'if", "Damsyik"], "Makkah dan Madinah ialah dua kota suci, al-Haramain."),
"sira_147": ("Berapa kali Nabi ﷺ menunaikan haji selepas Hijrah?", ["Sekali, Haji Perpisahan", "Tiga kali", "Setiap tahun", "Tidak pernah"], "Baginda hanya menunaikan satu haji selepas Hijrah: Haji Perpisahan, pada tahun 10 Hijrah."),
"sira_148": ("Menurut Anas, apakah yang Nabi ﷺ lakukan apabila seorang Badwi menarik kuat jubahnya sambil meminta harta?", ["Baginda tersenyum dan memerintahkan supaya dia diberi sesuatu", "Baginda menghukumnya", "Baginda pergi tanpa berkata apa-apa", "Baginda menghalaunya"], "Nabi ﷺ berpaling kepadanya, ketawa, dan memerintahkan supaya dia diberi sesuatu."),
"sira_149": ("Kota manakah, tempat Masjid al-Aqsa, yang menjadi destinasi Isra'?", ["Baitulmaqdis", "Damsyik", "Kaherah", "Baghdad"], "Isra' membawa Nabi ﷺ dari Makkah ke Masjid al-Aqsa di Baitulmaqdis."),
"sira_150": ("Berapakah usia Nabi ﷺ ketika wafat?", ["Enam puluh tiga", "Empat puluh", "Lima puluh", "Lapan puluh"], "Baginda wafat pada usia enam puluh tiga tahun, pada tahun 11 Hijrah."),
}
